#include <QCoreApplication>
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QSet>
#include <QTextBoundaryFinder>
static QJsonObject read(const QString &path){QFile file(path);if(!file.open(QIODevice::ReadOnly))qFatal("Input missing");return QJsonDocument::fromJson(file.readAll()).object();}
static QString text(const QJsonArray &values){QList<char32_t> data;for(const auto &v:values)data.append(v.toInt());return QString::fromUcs4(data.constData(),data.size());}
static QJsonArray scalars(const QString &value){QJsonArray result;for(auto scalar:value.toUcs4())result.append(int(scalar));return result;}
static QList<int> utf16Boundaries(const QString &value){QTextBoundaryFinder finder(QTextBoundaryFinder::Grapheme,value);QList<int> result{0};int end;while((end=finder.toNextBoundary())>=0)result.append(end);return result;}
static QJsonArray boundaries(const QString &value){QJsonArray result;for(auto end:utf16Boundaries(value))result.append(value.left(end).toUcs4().size());return result;}
static QString filter(const QString &value,const QSet<char32_t> &numbers,bool native){const auto ends=utf16Boundaries(value);QString result;for(int i=1;i<ends.size();++i){const auto part=value.mid(ends[i-1],ends[i]-ends[i-1]);const auto first=part.toUcs4().first();if(native ? numbers.contains(first):QChar::isNumber(first))result+=part;}return result;}
static QString prefix(const QString &value,int count){const auto ends=utf16Boundaries(value);return value.left(ends[qMin(count,int(ends.size()-1))]);}
int main(int argc,char **argv){QCoreApplication app(argc,argv);if(argc!=3)return 2;const QString root=argv[1];const auto semantics=read(root+"/native-otp-semantics.json"),native=read(root+"/native-otp-graphemes.json");QSet<char32_t> numbers;for(const auto &v:semantics.value("singleScalarNumbers").toArray())numbers.insert(v.toInt());QJsonArray numericDifferences,official,contexts,examples;int officialMatches=0,contextMatches=0,filterMatches=0,exampleMatches=0,plainMatches=0;
 for(char32_t cp=0;cp<=0x10ffff;++cp){if(cp>=0xd800 && cp<=0xdfff)continue;if(QChar::isNumber(cp)!=numbers.contains(cp))numericDifferences.append(QJsonObject{{"scalar",int(cp)},{"native",numbers.contains(cp)},{"qt",QChar::isNumber(cp)}});}
 for(const auto &v:native.value("officialTests").toArray()){const auto row=v.toObject();const auto input=text(row.value("scalars").toArray());const auto actual=boundaries(input);const bool equal=actual==row.value("boundaries").toArray();officialMatches+=equal;official.append(QJsonObject{{"index",row.value("index")},{"boundaries",actual},{"matchesNative",equal}});}
 for(const auto &v:native.value("markContexts").toArray()){const auto row=v.toObject();const auto input=text(QJsonArray{row.value("base"),row.value("mark"),0x32}),filtered=filter(input,numbers,true);const auto actual=boundaries(input);const bool equal=actual==row.value("boundaries").toArray(),filterEqual=scalars(filtered)==row.value("filteredScalars").toArray() && scalars(prefix(filtered,1))==row.value("prefixOneScalars").toArray();contextMatches+=equal;filterMatches+=filterEqual;contexts.append(QJsonObject{{"base",row.value("base")},{"mark",row.value("mark")},{"boundaries",actual},{"matchesNative",equal},{"filteredScalars",scalars(filtered)},{"prefixOneScalars",scalars(prefix(filtered,1))},{"filterMatchesNative",filterEqual}});}
 for(const auto &v:semantics.value("examples").toArray()){const auto row=v.toObject();const auto input=text(row.value("input").toObject().value("scalars").toArray());const auto result=scalars(prefix(filter(input,numbers,true),row.value("length").toInt())),plain=scalars(prefix(filter(input,numbers,false),row.value("length").toInt()));const bool equal=result==row.value("result").toObject().value("scalars").toArray(),plainEqual=plain==row.value("result").toObject().value("scalars").toArray();exampleMatches+=equal;plainMatches+=plainEqual;examples.append(QJsonObject{{"case",row.value("case")},{"length",row.value("length")},{"scalars",result},{"plainQtScalars",plain},{"matchesNative",equal},{"plainQtMatchesNative",plainEqual}});}
 QJsonObject result{{"reference",semantics.value("reference")},{"qt",qVersion()},{"qcharUnicodeVersion",int(QChar::currentUnicodeVersion())},{"scope","Original Qt boundary finder and QChar numeric classifier diagnostics; source-number-table variant is a measured candidate only"},{"singleScalarNumericDifferences",numericDifferences},{"officialTests",official},{"markContexts",contexts},{"examples",examples},{"summary",QJsonObject{{"nativeNumbers",numbers.size()},{"numericScalarDifferences",numericDifferences.size()},{"nativeBoundaryVectorMatches",officialMatches},{"boundaryVectors",official.size()},{"nativeMarkBoundaryMatches",contextMatches},{"markContexts",contexts.size()},{"nativeMarkFilterMatches",filterMatches},{"nativeExampleMatches",exampleMatches},{"examples",examples.size()},{"plainQtExampleMatches",plainMatches}}}};QFile out(argv[2]);if(!out.open(QIODevice::WriteOnly))return 3;out.write(QJsonDocument(result).toJson());qInfo().noquote()<<QJsonDocument(result.value("summary").toObject()).toJson();}
